// Tiny router: handle({ method, path, body }) -> { status, body }.
const RESERVATION_ERRORS = {
  INVALID_QTY: 400,
  INVALID_TTL: 400,
  INSUFFICIENT_STOCK: 409,
  RESERVATION_NOT_FOUND: 404,
  RESERVATION_EXPIRED: 410,
};

function reservationError(e) {
  const status = RESERVATION_ERRORS[e.message];
  if (!status) throw e;
  return { status, body: { error: e.message } };
}

function createApi(store) {
  return function handle({ method, path, body = {} }) {
    const stockMatch = path.match(/^\/stock\/([^/]+)$/);
    if (method === 'GET' && stockMatch) {
      const sku = decodeURIComponent(stockMatch[1]);
      return { status: 200, body: { sku, stock: store.getStock(sku), available: store.getAvailable(sku) } };
    }
    if (method === 'POST' && path === '/stock') {
      try {
        store.addItem(body.sku, body.qty);
        return { status: 201, body: { sku: body.sku, stock: store.getStock(body.sku) } };
      } catch (e) {
        return { status: 400, body: { error: e.message } };
      }
    }
    if (method === 'POST' && path === '/reservations') {
      try {
        return { status: 201, body: { id: store.reserve(body.sku, body.qty, body.ttlMs) } };
      } catch (e) {
        return reservationError(e);
      }
    }
    const confirmMatch = path.match(/^\/reservations\/([^/]+)\/confirm$/);
    if (method === 'POST' && confirmMatch) {
      try {
        return { status: 200, body: store.confirm(decodeURIComponent(confirmMatch[1])) };
      } catch (e) {
        return reservationError(e);
      }
    }
    const reservationMatch = path.match(/^\/reservations\/([^/]+)$/);
    if (method === 'DELETE' && reservationMatch) {
      store.release(decodeURIComponent(reservationMatch[1]));
      return { status: 204, body: null };
    }
    return { status: 404, body: { error: 'NOT_FOUND' } };
  };
}

module.exports = { createApi };
EOF
cat > test/reservations.test.js <<'EOF'
const assert = require('assert');
const { createStore } = require('../src/store');
const { createApi } = require('../src/api');

function setup(qty = 10) {
  let now = 1000;
  const s = createStore({ clock: () => now });
  s.addItem('A', qty);
  return { s, advance: (ms) => { now += ms; } };
}

test('reserve returns unique string ids', () => {
  const { s } = setup();
  const a = s.reserve('A', 1, 100);
  const b = s.reserve('A', 1, 100);
  assert.strictEqual(typeof a, 'string');
  assert.notStrictEqual(a, b);
});
test('reserve validates qty', () => {
  const { s } = setup();
  for (const q of [0, -1, 1.5, '2', undefined]) assert.throws(() => s.reserve('A', q, 100), /INVALID_QTY/);
});
test('reserve rejects more than available', () => {
  const { s } = setup(5);
  s.reserve('A', 3, 100);
  assert.throws(() => s.reserve('A', 3, 100), /INSUFFICIENT_STOCK/);
  assert.throws(() => s.reserve('nope', 1, 100), /INSUFFICIENT_STOCK/);
  s.reserve('A', 2, 100);
  assert.strictEqual(s.getAvailable('A'), 0);
});
test('reserve rejects bad ttl', () => {
  const { s } = setup();
  for (const t of [0, -5, undefined, NaN, Infinity, '100']) assert.throws(() => s.reserve('A', 1, t), /INVALID_TTL/);
});
test('available excludes active reservations; stock is physical', () => {
  const { s } = setup(10);
  s.reserve('A', 4, 100);
  assert.strictEqual(s.getAvailable('A'), 6);
  assert.strictEqual(s.getStock('A'), 10);
  assert.strictEqual(s.getAvailable('nope'), 0);
});
test('reservation expires exactly at creation + ttl', () => {
  const { s, advance } = setup(10);
  s.reserve('A', 4, 100);
  advance(99);
  assert.strictEqual(s.getAvailable('A'), 6);
  advance(1);
  assert.strictEqual(s.getAvailable('A'), 10);
  s.reserve('A', 10, 100);
});
test('confirm sells reserved stock', () => {
  const { s } = setup(10);
  const id = s.reserve('A', 4, 100);
  assert.deepStrictEqual(s.confirm(id), { sku: 'A', stock: 6 });
  assert.strictEqual(s.getStock('A'), 6);
  assert.strictEqual(s.getAvailable('A'), 6);
});
test('confirm unknown, released or confirmed id throws NOT_FOUND', () => {
  const { s } = setup();
  assert.throws(() => s.confirm('missing'), /RESERVATION_NOT_FOUND/);
  const a = s.reserve('A', 1, 100);
  s.release(a);
  assert.throws(() => s.confirm(a), /RESERVATION_NOT_FOUND/);
  const b = s.reserve('A', 1, 100);
  s.confirm(b);
  assert.throws(() => s.confirm(b), /RESERVATION_NOT_FOUND/);
  assert.strictEqual(s.getStock('A'), 9);
});
test('confirm expired throws EXPIRED and leaves stock untouched', () => {
  const { s, advance } = setup(10);
  const id = s.reserve('A', 4, 100);
  advance(100);
  assert.throws(() => s.confirm(id), /RESERVATION_EXPIRED/);
  assert.throws(() => s.confirm(id), /RESERVATION_EXPIRED/);
  assert.strictEqual(s.getStock('A'), 10);
});
test('release frees stock and is idempotent', () => {
  const { s } = setup(10);
  const id = s.reserve('A', 4, 100);
  s.release(id);
  s.release(id);
  s.release('missing');
  assert.strictEqual(s.getAvailable('A'), 10);
  assert.strictEqual(s.getStock('A'), 10);
});
test('removeItem cannot take reserved stock', () => {
  const { s, advance } = setup(10);
  s.reserve('A', 4, 100);
  assert.throws(() => s.removeItem('A', 7), /INSUFFICIENT_STOCK/);
  s.removeItem('A', 6);
  assert.strictEqual(s.getStock('A'), 4);
  advance(100);
  s.removeItem('A', 4);
  assert.strictEqual(s.getStock('A'), 0);
});
test('reservations are per sku', () => {
  const { s } = setup(5);
  s.addItem('B', 5);
  s.reserve('A', 5, 100);
  assert.strictEqual(s.getAvailable('B'), 5);
});

function apiSetup() {
  let now = 0;
  const api = createApi(createStore({ clock: () => now }));
  api({ method: 'POST', path: '/stock', body: { sku: 'A', qty: 10 } });
  return { api, advance: (ms) => { now += ms; } };
}

test('GET /stock includes available', () => {
  const { api } = apiSetup();
  api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 3, ttlMs: 50 } });
  assert.deepStrictEqual(api({ method: 'GET', path: '/stock/A' }), { status: 200, body: { sku: 'A', stock: 10, available: 7 } });
});
test('POST /reservations status codes', () => {
  const { api } = apiSetup();
  const ok = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 3, ttlMs: 50 } });
  assert.strictEqual(ok.status, 201);
  assert.strictEqual(typeof ok.body.id, 'string');
  assert.deepStrictEqual(api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 8, ttlMs: 50 } }), { status: 409, body: { error: 'INSUFFICIENT_STOCK' } });
  assert.deepStrictEqual(api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 0, ttlMs: 50 } }), { status: 400, body: { error: 'INVALID_QTY' } });
  assert.deepStrictEqual(api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 1 } }), { status: 400, body: { error: 'INVALID_TTL' } });
});
test('POST /reservations/:id/confirm status codes', () => {
  const { api, advance } = apiSetup();
  const id = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 3, ttlMs: 50 } }).body.id;
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${id}/confirm` }), { status: 200, body: { sku: 'A', stock: 7 } });
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${id}/confirm` }), { status: 404, body: { error: 'RESERVATION_NOT_FOUND' } });
  const late = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 1, ttlMs: 50 } }).body.id;
  advance(50);
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${late}/confirm` }), { status: 410, body: { error: 'RESERVATION_EXPIRED' } });
});
test('DELETE /reservations/:id returns 204 and releases', () => {
  const { api } = apiSetup();
  const id = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 3, ttlMs: 50 } }).body.id;
  assert.strictEqual(api({ method: 'DELETE', path: `/reservations/${id}` }).status, 204);
  assert.strictEqual(api({ method: 'DELETE', path: `/reservations/${id}` }).status, 204);
  assert.strictEqual(api({ method: 'GET', path: '/stock/A' }).body.available, 10);
  assert.strictEqual(api({ method: 'POST', path: `/reservations/${id}/confirm` }).status, 404);
});
